                Button("New Catalog...") {
                    AppCommandCenter.shared.newCatalog()
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)

                Button("New Session...") {
                    AppCommandCenter.shared.newSession()
                }
                .buttonStyle(.bordered)
                .controlSize(.large)

                Button("Open Document...") {
                    AppCommandCenter.shared.openDocument()
                }
